import RNA, random, time, multiprocessing as mp, sys
target = '(.(((..(((((....(((((......))))))))))((((...((((.....))))))))(((..(((....)))))).(((...((((...((((......))))))))(((..(((.....))))))((.((....)))).((((....(((..(((......))))))((.((.....))))(((....))).(((((.....((.((......))))(((.....)))((....)).((((((......(((......)))((.....))...(((((((...))))))).......))))))......))))).....))))....)))...)))..)...(.((.((((....((....))((....))((((((...)))))).)))))).)'
N=len(target)
seed=''

def worker(seed):
    random.seed(seed)
    for _ in range(40):
        # perturb the seed at the junction / end regions more heavily
        s=list(seed)
        # heavy perturbation at ends (0-6, 340-400) and around 83,331
        for _ in range(random.randint(5,25)):
            r=random.random()
            if r<0.5:
                i=random.choice(list(range(0,8))+list(range(338,400))+[83,331,84,330,119,123,82,332])
            else:
                i=random.randrange(N)
            s[i]=random.choice('ACGU')
        start=''.join(s)
        try:
            seq,d=RNA.inverse_fold(start,target)
        except Exception:
            continue
        if d==0:
            st,_=RNA.fold_compound(seq).mfe()
            if st==target:
                return seq
    return None

if __name__=='__main__':
    t0=time.time()
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(640)):
            if r:
                print('SOLVED',r); sys.stdout.flush(); p.terminate(); break
            if time.time()-t0>170:
                p.terminate(); break
    print('done',time.time()-t0)
